#!/usr/bin/env bash
set -euo pipefail

export PYTHONPATH="D:/OPENVELA/prebuilts/tools/python/dist-packages${PYTHONPATH:+:${PYTHONPATH}}"

exec /c/Users/Q1KO/AppData/Local/Programs/Python/Python312/python.exe \
  /d/OPENVELA/tools/windows/kconfig-compat/kconfig-conf.py "$@"
param(
  [string]$Port = 'COM7'
)

$ErrorActionPreference = 'Stop'
$statePath = Join-Path $env:LOCALAPPDATA 'openvela\mimo-bridge.json'
if (-not (Test-Path -LiteralPath $statePath)) {
  throw 'Start the local MiMo Token Plan bridge first.'
}

$bridge = Get-Content -LiteralPath $statePath -Raw | ConvertFrom-Json
$boardToken = [string]$bridge.board_token
if ([string]::IsNullOrWhiteSpace($boardToken) -or $boardToken.Length -gt 12) {
  throw 'Bridge token is too long for the ESP32-S3 NSH command. Restart the local bridge, then rerun this script.'
}
$serial = [System.IO.Ports.SerialPort]::new(
  $Port, 115200, [System.IO.Ports.Parity]::None, 8,
  [System.IO.Ports.StopBits]::One
)
$serial.Encoding = [System.Text.Encoding]::UTF8
$serial.NewLine = "`n"
$serial.DtrEnable = $false
$serial.RtsEnable = $false

function Read-Until([string]$prompt, [int]$timeoutMs, [bool]$display = $true) {
  $buffer = [System.Text.StringBuilder]::new()
  $deadline = [DateTime]::UtcNow.AddMilliseconds($timeoutMs)
  while ([DateTime]::UtcNow -lt $deadline) {
    Start-Sleep -Milliseconds 100
    $text = $serial.ReadExisting()
    if ($text) {
      [void]$buffer.Append($text)
      if ($display) { Write-Host $text -NoNewline }
      if ($buffer.ToString().Contains($prompt.Trim())) { return $true }
    }
  }
  return $false
}

function Read-Shell([int]$timeoutMs) {
  $buffer = [System.Text.StringBuilder]::new()
  $deadline = [DateTime]::UtcNow.AddMilliseconds($timeoutMs)
  while ([DateTime]::UtcNow -lt $deadline) {
    Start-Sleep -Milliseconds 100
    $text = $serial.ReadExisting()
    if ($text) {
      [void]$buffer.Append($text)
      Write-Host $text -NoNewline
      $all = $buffer.ToString()
      if ($all -match 'nsh>\s*$' -or $all -match 'vela>\s*$') { return $all }
    }
  }
  throw 'Timed out waiting for an NSH or Vela prompt.'
}

function Send-Command([string]$command, [string]$prompt = 'vela>', [int]$timeoutMs = 15000, [bool]$sensitive = $false) {
  $shown = if ($sensitive) { 'set_llm <local MiMo bridge> mimo-v2.5 ********' } else { $command }
  Write-Host ">> $shown"
  $serial.Write("$command`n")
  if (-not (Read-Until $prompt $timeoutMs (-not $sensitive))) {
    throw "Timed out waiting for '$prompt' after: $shown"
  }
}

try {
  $serial.Open()
  Start-Sleep -Milliseconds 500
  $shell = $serial.ReadExisting()
  if ($shell -notmatch 'nsh>' -and $shell -notmatch 'vela>') {
    $serial.Write("`n")
    $shell += Read-Shell 5000
  }
  if ($shell -match 'nsh>') {
    $serial.Write("ai_agent`n")
    if (-not (Read-Until 'vela>' 15000)) { throw 'AI Agent did not start.' }
  } elseif ($shell -notmatch 'vela>') {
    throw 'No NSH or Vela prompt received from the board.'
  }

  $url = "http://$($bridge.host):$($bridge.port)/v1"
  Send-Command "set_llm $url mimo-v2.5 $boardToken" 'vela>' 20000 $true
  Send-Command 'router_status'
  Send-Command 'ask hello' 'vela>' 15000
  Write-Host 'Waiting for the MiMo bridge response...'
  $deadline = [DateTime]::UtcNow.AddSeconds(45)
  while ([DateTime]::UtcNow -lt $deadline) {
    Start-Sleep -Milliseconds 200
    $text = $serial.ReadExisting()
    if ($text) {
      Write-Host $text -NoNewline
      if ($text -match '\[Agent\]:') { break }
    }
  }
  Write-Host "`nMiMo bridge configuration session finished."
} finally {
  if ($serial.IsOpen) { $serial.Close() }
}
param(
  [string]$Port = 'COM7',
  [int]$TimeoutSeconds = 180
)

$logPath = 'D:\OPENVELA\foodloop-button-test.log'
$utf8 = New-Object System.Text.UTF8Encoding($false)
$serial = [System.IO.Ports.SerialPort]::new(
  $Port, 115200, [System.IO.Ports.Parity]::None, 8,
  [System.IO.Ports.StopBits]::One
)
$serial.NewLine = "`n"
$serial.Encoding = $utf8
$serial.ReadTimeout = 200

try {
  $serial.Open()
  Start-Sleep -Milliseconds 500
  $serial.Write("`nfoodloop`n")
  $deadline = [DateTime]::UtcNow.AddSeconds($TimeoutSeconds)

