function Read-Board([string]$expectedPrompt, [int]$timeoutMs, [bool]$display = $true) {
  $buffer = [System.Text.StringBuilder]::new()
  $deadline = [DateTime]::UtcNow.AddMilliseconds($timeoutMs)

  while ([DateTime]::UtcNow -lt $deadline) {
    Start-Sleep -Milliseconds 100
    $text = $serial.ReadExisting()
    if ($text) {
      [void]$buffer.Append($text)
      if ($display) {
        Write-Host $text -NoNewline
      }
      if ($buffer.ToString().Contains($expectedPrompt.Trim())) {
        return $buffer.ToString()
      }
    }
  }

  throw "Timed out waiting for '$expectedPrompt'."
}

function Read-ShellPrompt([int]$timeoutMs) {
  $buffer = [System.Text.StringBuilder]::new()
  $deadline = [DateTime]::UtcNow.AddMilliseconds($timeoutMs)

  while ([DateTime]::UtcNow -lt $deadline) {
    Start-Sleep -Milliseconds 100
    $text = $serial.ReadExisting()
    if ($text) {
      [void]$buffer.Append($text)
      Write-Host $text -NoNewline
      $all = $buffer.ToString()
      if ($all -match 'nsh>\s*$' -or $all -match 'vela>\s*$') {
        return $all
      }
    }
  }

  throw 'Timed out waiting for an NSH or Vela prompt.'
}

function Send-Board([string]$command, [string]$prompt = 'vela> ', [int]$timeoutMs = 15000, [bool]$sensitive = $false) {
  $shown = if ($sensitive) { 'set_llm <Token Plan endpoint> mimo-v2.5 ********' } else { $command }
  Write-Host ">> $shown"
  $serial.Write("$command`n")
  [void](Read-Board $prompt $timeoutMs (-not $sensitive))
}

